import Image from "next/image";
import type { ComponentProps, CSSProperties } from "react";
import { getDeviceFrame, type DeviceFrame, type DeviceModel } from "./device-frames";
import "./device.css";

export { deviceFrames } from "./device-frames";
export type { DeviceFrame, DeviceModel } from "./device-frames";

export type DeviceProps = ComponentProps<"div"> & {
  model?: DeviceModel;
  frame?: DeviceFrame;
  frameSrc?: string;
  screenClassName?: string;
  screenStyle?: CSSProperties;
};

export function Device({ model = "iphone", frame: customFrame, frameSrc, children, className, style, screenClassName, screenStyle, ...props }: DeviceProps) {
  const frame = getDeviceFrame(model, customFrame);
  const { screen } = frame;
  return (
    <div {...props} data-slot="device" data-device={model} className={className} style={{ ...style, aspectRatio: `${frame.width} / ${frame.height}` }}>
      <div
        data-slot="device-screen"
        className={screenClassName}
        style={{
          ...screenStyle,
          left: `${screen.x / frame.width * 100}%`,
          top: `${screen.y / frame.height * 100}%`,
          width: `${screen.width / frame.width * 100}%`,
          height: `${screen.height / frame.height * 100}%`,
          borderRadius: `${screen.radius / screen.width * 100}% / ${screen.radius / screen.height * 100}%`,
        }}
      >
        {children}
      </div>
      <Image
        data-slot="device-frame"
        src={frameSrc ?? frame.src}
        width={frame.width}
        height={frame.height}
        alt=""
        aria-hidden="true"
        draggable={false}
        unoptimized
      />
    </div>
  );
}

export type DeviceModel = "iphone" | "ipad" | "macbook" | "android";

export type DeviceFrame = {
  name: string;
  src: string;
  width: number;
  height: number;
  screen: { x: number; y: number; width: number; height: number; radius: number };
};

export const deviceFrames: Record<DeviceModel, DeviceFrame> = {
  iphone: {
    name: "iPhone 17",
    src: "https://www.webmobilefirst.com/img/mockups/mockup-apple-iphone-17-2025-transparent.png",
    width: 388,
    height: 800,
    screen: { x: 16, y: 13, width: 356, height: 774, radius: 62 },
  },
  ipad: {
    name: "iPad Pro",
    src: "https://www.webmobilefirst.com/img/mockups/mockup-apple-ipad-pro-11-2018-transparent.png",
    width: 578,
    height: 800,
    screen: { x: 29, y: 31, width: 518, height: 740, radius: 12 },
  },
  macbook: {
    name: "MacBook Pro",
    src: "https://www.webmobilefirst.com/img/mockups/mockup-apple-macbook-pro-16-2021-transparent.png",
    width: 800,
    height: 489,
    screen: { x: 74, y: 18, width: 652, height: 422, radius: 3 },
  },
  android: {
    name: "Galaxy S26 Ultra",
    src: "https://www.webmobilefirst.com/img/mockups/mockup-samsung-galaxy-s26-ultra-2026-transparent.png",
    width: 385,
    height: 800,
    screen: { x: 11, y: 10, width: 361, height: 779, radius: 34 },
  },
};

export function getDeviceFrame(model: DeviceModel, customFrame?: DeviceFrame): DeviceFrame {
  const frame = customFrame ?? deviceFrames[model];
  if (!frame) throw new Error(`Unknown device model: ${model}`);
  const { width, height, screen, src } = frame;
  const values = [width, height, screen.x, screen.y, screen.width, screen.height, screen.radius];
  if (values.some((value) => !Number.isFinite(value)) || width <= 0 || height <= 0 || screen.width <= 0 || screen.height <= 0 || screen.x < 0 || screen.y < 0 || screen.radius < 0 || screen.x + screen.width > width || screen.y + screen.height > height || screen.radius > Math.min(screen.width, screen.height) / 2) {
    throw new Error("The device screen must fit inside its PNG frame.");
  }
  if (!src.trim()) throw new Error("A device frame image source is required.");
  return frame;
}

[data-slot="device"] {
  position: relative;
  isolation: isolate;
  width: 100%;
}

[data-slot="device-screen"] {
  position: absolute;
  overflow: hidden;
  background: var(--background, #fff);
  color: var(--foreground, #171717);
  container-type: inline-size;
}

[data-slot="device-frame"] {
  position: relative;
  display: block;
  width: 100%;
  height: auto;
  pointer-events: none;
  user-select: none;
}
